    const s=editor.schedule || {},mode=editor.mode || 'on_demand',stages=orderedNodes().filter(node=>node.type==='t'),root=nodes(editor).find(node=>node.type==='p'),schedules=(state.operations?.schedules || []).filter(value=>value.workflow_id===workflowId());
